import base64
import json
import socket
from html.parser import HTMLParser
from urllib.parse import urlsplit

HOST = "192.168.4.3"
PORT = 8080
TIMEOUT = 4.0


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        for key, value in attrs:
            if key.lower() == "href" and value:
                self.hrefs.append(value)


def http_get(path):
    request = (
        "GET " + path + " HTTP/1.1\r\n"
        "Host: " + HOST + "\r\n"
        "User-Agent: targeted-service-followup/1.0\r\n"
        "Accept: */*\r\n"
        "Connection: close\r\n\r\n"
    ).encode("ascii", "strict")
    result = {"host": HOST, "port": PORT, "path": path}
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            result["tcp_connected"] = True
            sock.settimeout(TIMEOUT)
            sock.sendall(request)
            chunks = []
            while True:
                try:
                    chunk = sock.recv(65536)
                except socket.timeout:
                    result["read_status"] = "timeout"
                    break
                if not chunk:
                    result["read_status"] = "peer_closed"
                    break
                chunks.append(chunk)
            raw = b"".join(chunks)
            result["raw_response_base64"] = base64.b64encode(raw).decode("ascii")
            result["raw_response_length"] = len(raw)
            header, separator, body = raw.partition(b"\r\n\r\n")
            result["header_text_lossy"] = header.decode("iso-8859-1", "replace")
            if not separator:
                result["http_header_separator_found"] = False
            else:
                result["http_header_separator_found"] = True
                result["body_length_as_received"] = len(body)
                result["body_for_link_parse_base64"] = base64.b64encode(body).decode("ascii")
    except Exception as exc:
        result["tcp_connected"] = False
        result["error"] = type(exc).__name__ + ": " + str(exc)
    return result


def advertised_local_paths(root_result):
    encoded = root_result.get("body_for_link_parse_base64")
    if not encoded:
        return []
    try:
        body = base64.b64decode(encoded)
        parser = LinkParser()
        parser.feed(body.decode("utf-8", "replace"))
    except Exception:
        return []
    paths = []
    seen = set()
    for href in parser.hrefs:
        parsed = urlsplit(href)
        if parsed.scheme or parsed.netloc or not parsed.path.startswith("/"):
            continue
        path = parsed.path
        if parsed.query:
            path += "?" + parsed.query
        if path not in seen:
            seen.add(path)
            paths.append(path)
    return paths


def main():
    observations = {
        "target": HOST,
        "tcp_http_checks": [],
        "coverage_note": "Direct TCP/HTTP checks are limited to TCP/8080 and same-host absolute paths linked from its root response. UDP scan scope is limited to Nmap's top 20 ports.",
    }
    root = http_get("/")
    observations["tcp_http_checks"].append(root)
    for path in advertised_local_paths(root):
        observations["tcp_http_checks"].append(http_get(path))

    try:
        from framework_evidence import run_tool
        observations["udp_scan_tool_envelope"] = run_tool([
            "nmap", "-sU", "-sV", "--top-ports", "20", "-n", "-oX", "-", HOST
        ])
    except Exception as exc:
        observations["udp_scan_error"] = type(exc).__name__ + ": " + str(exc)

    print(json.dumps(observations, ensure_ascii=False, default=str))


if __name__ == "__main__":
    main()

