import hashlib
import json
import os
import re
import sys

ARTIFACT = "llm_inputs/c1de26062772736eaf99c363c34acf6e6a404589b7371a878c90dad7ad8e55a3.json"
EXPECTED_SHA256 = "c1de26062772736eaf99c363c34acf6e6a404589b7371a878c90dad7ad8e55a3"
SOURCE_PATH = ["prior_observations"]


def candidate_paths():
    roots = [os.getcwd(), "/root", "/root/scripts", "/workspace", "/workspaces",
             "/mnt/data", "/app", "/archive", "/archives", "/data", "/tmp",
             "/home", "/srv", "/run", "/opt"]
    seen = set()
    for root in roots:
        root = os.path.abspath(root)
        direct = os.path.join(root, ARTIFACT)
        if direct not in seen:
            seen.add(direct)
            yield direct

    # Search only these plausible archive roots, without following symlinks or
    # traversing pseudo-filesystems. The exact artifact basename is required.
    basename = os.path.basename(ARTIFACT)
    excluded = {"proc", "sys", "dev", ".git", "node_modules", "__pycache__"}
    for root in roots:
        root = os.path.abspath(root)
        if not os.path.isdir(root):
            continue
        root_depth = root.rstrip(os.sep).count(os.sep)
        for current, dirs, files in os.walk(root, followlinks=False):
            depth = current.rstrip(os.sep).count(os.sep) - root_depth
            dirs[:] = [d for d in dirs if d not in excluded and not os.path.islink(os.path.join(current, d))]
            if depth >= 5:
                dirs[:] = []
            if basename in files:
                found = os.path.join(current, basename)
                if found not in seen:
                    seen.add(found)
                    yield found


def get_source(document):
    value = document
    for key in SOURCE_PATH:
        if not isinstance(value, dict) or key not in value:
            raise KeyError("source path component not present: " + key)
        value = value[key]
    return value


def strings_in(value, path="$[\"prior_observations\"]"):
    if isinstance(value, str):
        yield path, value
    elif isinstance(value, dict):
        for key, child in value.items():
            yield from strings_in(child, path + "[" + json.dumps(str(key)) + "]")
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from strings_in(child, path + "[" + str(index) + "]")


def assess(observations):
    ip_port = re.compile(r"(?<![\d.])192\.168\.4\.(?:25[0-5]|2[0-4]\d|1?\d?\d)(?::(\d{1,5}))?(?![\d.])")
    interaction = re.compile(r"\b(?:GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+\S+|https?://|\b(?:request|response|curl)\b", re.I)
    endpoints = []
    interactions = []
    for path, text in strings_in(observations):
        for match in ip_port.finditer(text):
            endpoints.append({"source_path": path, "match": match.group(0),
                              "context": text[max(0, match.start() - 140):min(len(text), match.end() + 180)]})
        if interaction.search(text):
            # Retain relevant lines or compact context, not an inferred interpretation.
            relevant = []
            for line in text.splitlines():
                if interaction.search(line) and len(relevant) < 12:
                    relevant.append(line[:1200])
            if not relevant:
                match = interaction.search(text)
                relevant = [text[max(0, match.start() - 180):min(len(text), match.end() + 260)]]
            interactions.append({"source_path": path, "evidence": relevant})
    unique = sorted({item["match"] for item in endpoints})
    return {
        "in_scope_endpoint_matches": endpoints,
        "unique_endpoint_values": unique,
        "interaction_pattern_evidence": interactions,
        "assessment_note": "These are textual matches in the retrieved observations, not independent network observations. Review the complete observations below to determine whether any endpoint and request pattern are explicitly documented and repeatable."
    }


def main():
    checked = []
    for path in candidate_paths():
        checked.append(path)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "rb") as stream:
                raw = stream.read()
        except OSError:
            continue
        digest = hashlib.sha256(raw).hexdigest()
        if digest != EXPECTED_SHA256:
            # Artifact filename alone is not sufficient to establish identity.
            continue
        try:
            document = json.loads(raw.decode("utf-8"))
            observations = get_source(document)
        except (UnicodeDecodeError, json.JSONDecodeError, KeyError, TypeError) as exc:
            print(json.dumps({"retrieval_status": "source_unusable", "source_artifact": ARTIFACT,
                              "source_path": '$["prior_observations"]', "sha256_verified": True,
                              "error": str(exc), "checked_paths": checked}, ensure_ascii=False))
            return
        result = {
            "retrieval_status": "complete",
            "source_artifact": ARTIFACT,
            "artifact_path": path,
            "expected_sha256": EXPECTED_SHA256,
            "observed_sha256": digest,
            "sha256_verified": True,
            "source_path": '$["prior_observations"]',
            "complete_prior_observations": observations,
            "focused_assessment": assess(observations)
        }
        print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
        return
    print(json.dumps({
        "retrieval_status": "unavailable",
        "source_artifact": ARTIFACT,
        "expected_sha256": EXPECTED_SHA256,
        "source_path": '$["prior_observations"]',
        "checked_paths": checked,
        "error": "The exact artifact was not found and SHA-256 verified at the checked locations; its prior_observations contents and endpoint/interaction details remain unknown."
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

