import hashlib
import json
import os
import sys

ARTIFACT = "11b936be792a9f52272064174bf24b7831df25c1cb37965c01d9de6e904a3f07.json"
EXPECTED_SHA256 = "11b936be792a9f52272064174bf24b7831df25c1cb37965c01d9de6e904a3f07"
SOURCE_PATH = '$["prior_observations"]'

# Check only the exact supplied artifact, under the archive directories considered
# by the prior retrieval, plus the current working directory's corresponding path.
roots = [
    os.path.join(os.getcwd(), "llm_inputs"),
    "/root/scripts/llm_inputs",
    "/root/llm_inputs",
    "/workspace/llm_inputs",
    "/workspaces/llm_inputs",
    "/mnt/data/llm_inputs",
    "/app/llm_inputs",
    "/archive/llm_inputs",
    "/archives/llm_inputs",
    "/data/llm_inputs",
    "/tmp/llm_inputs",
    "/home/llm_inputs",
    "/srv/llm_inputs",
    "/run/llm_inputs",
    "/opt/llm_inputs",
]

checked = []
found = None
for root in roots:
    path = os.path.join(root, ARTIFACT)
    if path in checked:
        continue
    checked.append(path)
    if os.path.isfile(path):
        found = path
        break

result = {
    "source_artifact": "llm_inputs/" + ARTIFACT,
    "expected_sha256": EXPECTED_SHA256,
    "source_path": SOURCE_PATH,
    "checked_paths": checked,
}

if found is None:
    result.update({
        "retrieval_status": "unavailable",
        "error": "The exact metadata-identified artifact was not present at the checked archive locations; the requested observations and endpoint/interaction details therefore remain unknown.",
    })
else:
    try:
        with open(found, "rb") as f:
            raw = f.read()
        actual_sha256 = hashlib.sha256(raw).hexdigest()
        result["located_path"] = found
        result["actual_sha256"] = actual_sha256
        if actual_sha256 != EXPECTED_SHA256:
            result.update({
                "retrieval_status": "integrity_mismatch",
                "error": "A file with the expected artifact name was found, but its SHA-256 does not match the supplied metadata; it was not treated as the requested artifact.",
            })
        else:
            try:
                document = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                result.update({
                    "retrieval_status": "parse_error",
                    "error": "The hash-verified artifact could not be decoded as UTF-8 JSON: " + str(exc),
                })
            else:
                if not isinstance(document, dict) or "prior_observations" not in document:
                    result.update({
                        "retrieval_status": "source_path_missing",
                        "error": "The exact hash-verified artifact does not contain the requested top-level prior_observations member; no endpoint or interaction omission is inferred beyond that path check.",
                    })
                else:
                    result.update({
                        "retrieval_status": "retrieved",
                        "source_path_status": "present",
                        "prior_observations": document["prior_observations"],
                        "assessment_note": "The complete retrieved prior_observations value is included above. Assess endpoint and repeatable interaction details from these records; this script does not infer their presence or absence from artifact metadata alone.",
                    })
    except OSError as exc:
        result.update({
            "retrieval_status": "read_error",
            "located_path": found,
            "error": "The exact named artifact was located but could not be read: " + str(exc),
        })

json.dump(result, sys.stdout, ensure_ascii=False, separators=(",", ":"))
sys.stdout.write("\n")

