import json
import re

import framework_evidence

URL = "http://192.168.4.3:8080/output"
FIELDS = ("p", "g", "pubA", "pubB", "ciphertext")


def response_stdout(envelope):
    """Collect stdout streams from the helper envelope without discarding it."""
    streams = []
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs", [])
        if isinstance(runs, list):
            for run in runs:
                if isinstance(run, dict) and isinstance(run.get("stdout"), str):
                    streams.append(run["stdout"])
    return "\n".join(streams)


def inspect_response(text):
    result = {"http_status": None, "fields": {}, "missing_fields": []}
    status_match = re.search(r"^HTTP/\S+\s+(\d{3})", text, re.MULTILINE)
    if status_match:
        result["http_status"] = int(status_match.group(1))

    for field in FIELDS:
        match = re.search(
            r"(?:^|\n)\s*" + re.escape(field) + r"\s*:\s*([0-9a-fA-F]+)\s*(?:\r?$)",
            text,
            re.MULTILINE,
        )
        if match:
            result["fields"][field] = match.group(1)
        else:
            result["missing_fields"].append(field)
    return result


records = []
for index in range(1, 4):
    command = [
        "curl", "--silent", "--show-error", "--include", "--max-time", "10",
        "--request", "GET", URL,
    ]
    try:
        envelope = framework_evidence.run_tool(command)
        records.append({
            "request_index": index,
            "command": command,
            "tool_result": envelope,
            "inspection": inspect_response(response_stdout(envelope)),
        })
    except Exception as exc:
        records.append({
            "request_index": index,
            "command": command,
            "tool_error": {"type": type(exc).__name__, "message": str(exc)},
            "inspection": {"http_status": None, "fields": {}, "missing_fields": list(FIELDS)},
        })

comparisons = []
for left in range(len(records)):
    for right in range(left + 1, len(records)):
        left_fields = records[left]["inspection"]["fields"]
        right_fields = records[right]["inspection"]["fields"]
        field_comparison = {}
        for field in FIELDS:
            if field in left_fields and field in right_fields:
                field_comparison[field] = {
                    "equal": left_fields[field] == right_fields[field],
                    "left": left_fields[field],
                    "right": right_fields[field],
                }
            else:
                field_comparison[field] = {"comparable": False}
        comparisons.append({
            "requests": [records[left]["request_index"], records[right]["request_index"]],
            "fields": field_comparison,
        })

print(json.dumps({
    "endpoint": URL,
    "request_count": len(records),
    "requests": records,
    "pairwise_comparisons": comparisons,
    "assessment_note": "Only values present in captured responses are compared; absent or incomplete fields are not evidence that other hypotheses are exhausted.",
}, ensure_ascii=False))

