import hashlib
import json
import os
import re
import sys

EXTENSIONS = {".json", ".jsonl", ".txt", ".md", ".log", ".yaml", ".yml", ".html", ".xml", ".csv", ".rst"}
SKIP_DIRS = {".cache", ".git", ".venv", "venv", "node_modules", "__pycache__", "scripts"}
TERMS = re.compile(r"diffie|hellman|\bdh\b|modulus|generator|public.?key|exchange|transcript|shared.?secret|ciphertext|crypto", re.I)
PARAM_KEYS = re.compile(r"(^|[^a-z])(p|q|prime|modulus|n|g|generator|public.?[ab12]|[ab12].?public|ya|yb|alice.?public|bob.?public|client.?public|server.?public|public.?key|peer.?key|endpoint|host|port|url|transcript|ciphertext|nonce|salt|validation|proof)([^a-z]|$)", re.I)


def candidate_roots():
    roots = [os.getcwd(), "/tmp", "/root", "/home", "/opt", "/var/tmp", "/mnt", "/workspace"]
    seen = set()
    result = []
    for item in roots:
        if os.path.isdir(item):
            real = os.path.realpath(item)
            if real not in seen:
                seen.add(real)
                result.append(real)
    return result


def walk_documents(roots):
    seen_files = set()
    inspected = []
    errors = []
    excluded = {os.path.realpath("/root/scripts")}
    for root in roots:
        for current, dirs, files in os.walk(root, followlinks=False):
            dirs[:] = [d for d in dirs if d not in SKIP_DIRS and not os.path.islink(os.path.join(current, d))]
            real_current = os.path.realpath(current)
            if any(real_current == x or real_current.startswith(x + os.sep) for x in excluded):
                dirs[:] = []
                continue
            for name in files:
                path = os.path.join(current, name)
                real = os.path.realpath(path)
                suffix = os.path.splitext(name)[1].lower()
                named_record = bool(re.search(r"crypto|challenge|observ|evidence|exchange|transcript|service", name, re.I))
                if suffix not in EXTENSIONS and not (not suffix and named_record):
                    continue
                if real in seen_files or not os.path.isfile(path):
                    continue
                seen_files.add(real)
                inspected.append(path)
    return inspected, errors


def walk_json(value, path="$", out=None, context=""):
    if out is None:
        out = []
    if isinstance(value, dict):
        keys_text = " ".join(str(k) for k in value.keys())
        local_context = context + " " + keys_text
        # Preserve relevant named values exactly, along with their JSON paths.
        if TERMS.search(local_context):
            for key, item in value.items():
                if PARAM_KEYS.search(str(key)) and not isinstance(item, (dict, list)):
                    out.append({"json_path": path + "." + str(key), "key": str(key), "value": item})
        for key, item in value.items():
            walk_json(item, path + "." + str(key), out, local_context)
    elif isinstance(value, list):
        for index, item in enumerate(value):
            walk_json(item, path + "[" + str(index) + "]", out, context)
    return out


def main():
    roots = candidate_roots()
    paths, _ = walk_documents(roots)
    matches = []
    read_errors = []
    for path in paths:
        try:
            with open(path, "rb") as stream:
                raw = stream.read()
            digest = hashlib.sha256(raw).hexdigest()
            text = raw.decode("utf-8", errors="replace")
        except Exception as exc:
            read_errors.append({"path": path, "error": str(exc)})
            continue

        excerpts = []
        for line_number, line in enumerate(text.splitlines(), 1):
            if TERMS.search(line):
                excerpt = line.strip()
                if len(excerpt) > 3000:
                    excerpt = excerpt[:3000] + "...[line excerpt truncated]"
                excerpts.append({"line": line_number, "text": excerpt})

        fields = []
        if os.path.splitext(path)[1].lower() in {".json", ".jsonl"}:
            try:
                parsed = json.loads(text)
                fields = walk_json(parsed)
            except Exception:
                # Preserve text excerpts and record the parse failure below.
                pass

        if excerpts or fields:
            matches.append({
                "source_path": path,
                "sha256": digest,
                "bytes": len(raw),
                "relevant_excerpts": excerpts,
                "parameter_or_identity_fields": fields,
                "note": "Fields are extracted by name and remain candidates; establish that they belong to the same observed exchange using the source context."
            })

    report = {
        "purpose": "Focused extraction from local existing records; no network discovery or service request was performed.",
        "examined_roots": roots,
        "excluded_generated_scripts": "/root/scripts",
        "document_paths_considered": len(paths),
        "matching_documents": matches,
        "read_errors": read_errors,
        "coverage_note": "Only readable document files under the listed roots were examined. A lack of matches is not evidence that records are absent elsewhere. Generated scripts were excluded as evidence.",
        "assessment_note": "Compare source paths and exchange identity before combining parameters. Retain any transcript, service response, ciphertext, or validation material as independent evidence rather than treating a parameter-name match as proof."
    }
    print(json.dumps(report, ensure_ascii=False))


if __name__ == "__main__":
    main()

