import hashlib
import json
import os
import re
import sys

ROOTS = ["/root/scripts", "/tmp", "/root", "/home", "/opt", "/var/tmp", "/mnt"]
EXCLUDED = {os.path.realpath("/root/scripts")}
TEXT_SUFFIXES = {
    ".txt", ".text", ".json", ".jsonl", ".log", ".md", ".html", ".htm",
    ".xml", ".csv", ".yaml", ".yml", ".conf", ".ini", ".out", ".trace"
}
MAX_FILE_BYTES = 20 * 1024 * 1024
TERMS = re.compile(
    r"diffie[\s_-]*hellman|\bdh\b|modulus|\bgenerator\b|"
    r"public[ _-]?(?:value|key)|ciphertext|shared[ _-]?secret|"
    r"transcript|192\.168\.4\.3|192\.168\.4\.0/24",
    re.IGNORECASE,
)
EXCHANGE_CONTEXT = re.compile(
    r"diffie[\s_-]*hellman|\bdh\b|modulus|\bgenerator\b|"
    r"public[ _-]?(?:value|key)|ciphertext|shared[ _-]?secret|"
    r"transcript|service|exchange|192\.168\.4\.3",
    re.IGNORECASE,
)


def likely_text(path):
    suffix = os.path.splitext(path)[1].lower()
    if suffix in TEXT_SUFFIXES:
        return True
    return not suffix and os.path.basename(path).lower() in {
        "transcript", "challenge", "record", "output", "evidence", "readme"
    }


def main():
    examined = 0
    unreadable = []
    oversized = []
    hits = []
    seen = set()

    for root in ROOTS:
        if not os.path.exists(root):
            continue
        for current, dirs, files in os.walk(root, followlinks=False):
            real_current = os.path.realpath(current)
            if any(real_current == ex or real_current.startswith(ex + os.sep) for ex in EXCLUDED):
                dirs[:] = []
                continue
            dirs[:] = [d for d in dirs if d not in {".git", "node_modules", "__pycache__"}]
            for name in files:
                path = os.path.join(current, name)
                real_path = os.path.realpath(path)
                if real_path in seen or not likely_text(path):
                    continue
                seen.add(real_path)
                try:
                    size = os.path.getsize(path)
                except OSError as exc:
                    unreadable.append({"source_path": path, "error": str(exc)})
                    continue
                if size > MAX_FILE_BYTES:
                    oversized.append({"source_path": path, "bytes": size, "reason": "over 20 MiB search limit"})
                    continue
                try:
                    with open(path, "rb") as f:
                        raw = f.read()
                    text = raw.decode("utf-8")
                except (OSError, UnicodeDecodeError) as exc:
                    unreadable.append({"source_path": path, "error": type(exc).__name__ + ": " + str(exc)})
                    continue
                examined += 1
                matching_lines = []
                for line_no, line in enumerate(text.splitlines(), 1):
                    if TERMS.search(line):
                        matching_lines.append({"line": line_no, "text": line.strip()[:500]})
                if matching_lines:
                    full_context = bool(EXCHANGE_CONTEXT.search(text))
                    hits.append({
                        "source_path": path,
                        "sha256": hashlib.sha256(raw).hexdigest(),
                        "bytes": size,
                        "exchange_context_in_file": full_context,
                        "relevant_excerpts": matching_lines[:12],
                        "additional_matching_lines_omitted": max(0, len(matching_lines) - 12),
                    })

    report = {
        "purpose": "Focused retrieval of local original-record candidates only; no network discovery or service request was performed.",
        "scope": {"roots_considered": ROOTS, "generated_scripts_excluded": sorted(EXCLUDED)},
        "search": {
            "readable_text_files_examined": examined,
