import json
import re
import sys

import framework_evidence

URL = "http://192.168.4.3:8080/output"

ALIASES = {
    "modulus": {"p", "modulus", "primemodulus", "dhmodulus"},
    "generator": {"g", "generator", "dhgenerator"},
    "public_a": {
        "a", "publica", "publicvaluea", "publickeya", "alicepublic",
        "public1", "publicvalue1", "publickey1", "pubkey1",
    },
    "public_b": {
        "b", "publicb", "publicvalueb", "publickeyb", "bobpublic",
        "public2", "publicvalue2", "publickey2", "pubkey2",
    },
    "exchange_identity_or_context": {
        "exchangeid", "sessionid", "challengeid", "identity", "context",
        "exchange", "challenge", "transcriptid",
    },
    "validation_material": {
        "validation", "validationmaterial", "validationtoken", "proof",
        "signature", "checksum", "verification", "tag", "mac",
    },
}


def normalize(value):
    return re.sub(r"[^a-z0-9]", "", str(value).lower())


def display_scalar(value):
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    if value is None:
        return "null"
    return str(value)


def extract_from_json(value, path="$", found=None):
    if found is None:
        found = {name: [] for name in ALIASES}
    if isinstance(value, dict):
        for key, child in value.items():
            normalized = normalize(key)
            for field, aliases in ALIASES.items():
                if normalized in aliases and not isinstance(child, (dict, list)):
                    found[field].append({
                        "value": display_scalar(child),
                        "source": "json",
                        "path": path + "." + str(key),
                    })
            extract_from_json(child, path + "." + str(key), found)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            extract_from_json(child, path + "[" + str(index) + "]", found)
    return found


def extract_from_text(body, found):
    # Recognize explicitly labeled textual fields; retain the label and literal value.
    labels = {
        "modulus": r"(?:dh[_ -]?)?(?:modulus|prime|p)",
        "generator": r"(?:dh[_ -]?)?(?:generator|g)",
        "public_a": r"(?:public[_ -]?(?:value|key)?[_ -]?(?:a|1)|alice[_ -]?public|pubkey1)",
        "public_b": r"(?:public[_ -]?(?:value|key)?[_ -]?(?:b|2)|bob[_ -]?public|pubkey2)",
        "exchange_identity_or_context": r"(?:exchange[_ -]?id|session[_ -]?id|challenge[_ -]?id|context|transcript[_ -]?id)",
        "validation_material": r"(?:validation(?:[_ -]?material|[_ -]?token)?|proof|signature|checksum|verification|tag|mac)",
    }
    for field, label_pattern in labels.items():
        pattern = re.compile(
            r"(?im)^\s*[\"']?(" + label_pattern + r")[\"']?\s*[:=]\s*[\"']?([^\r\n,}\"']+)",
        )
        for match in pattern.finditer(body):
            literal = match.group(2).strip()
            if literal:
                found[field].append({
                    "value": literal,
                    "source": "labeled_response_text",
                    "label": match.group(1),
                    "offset": match.start(),
                })


def response_body(raw):
    # curl --include may contain interim/redirect response headers. Use the body
    # following the last HTTP header block, without changing the retained raw stream.
    matches = list(re.finditer(r"(?m)^HTTP/\S+\s+\d{3}[^\r\n]*\r?\n", raw))
    if not matches:
        return raw, "no_http_status_line_in_captured_output"
    start = matches[-1].end()
    separator = re.search(r"\r?\n\r?\n", raw[start:])
    if not separator:
        return "", "http_headers_found_but_body_separator_missing"
    body_start = start + separator.end()
    return raw[body_start:], "http_headers_and_body_separated"


def main():
    argv = ["curl", "--silent", "--show-error", "--include", "--max-time", "20", URL]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        print(json.dumps({
            "request": argv,
            "tool_run_error": str(exc),
            "parsing_status": "not_attempted",
            "field_coverage": {name: "unknown" for name in ALIASES},
        }, ensure_ascii=False))
        return 1

    if isinstance(envelope, dict):
        stdout = envelope.get("stdout", "")
        if not isinstance(stdout, str):
            stdout = ""
    else:
        stdout = ""

    body, framing_status = response_body(stdout)
    found = {name: [] for name in ALIASES}
    json_status = "not_json"
    try:
        parsed = json.loads(body)
        found = extract_from_json(parsed)
        json_status = "parsed"
    except (json.JSONDecodeError, TypeError):
        extract_from_text(body, found)

    # Text parsing can supplement JSON only when it yields explicitly labeled values.
    if json_status == "parsed":
        text_found = {name: [] for name in ALIASES}
        extract_from_text(body, text_found)
        for name in found:
            found[name].extend(text_found[name])

    fields = {}
    for name, entries in found.items():
        fields[name] = {"status": "found" if entries else "missing", "values": entries}

    complete = all(fields[name]["status"] == "found" for name in ("modulus", "generator", "public_a", "public_b"))
    result = {
        "request": argv,
        "tool_run": envelope,
        "raw_response_stdout": stdout,
        "response_body": body,
        "response_framing_status": framing_status,
        "body_json_status": json_status,
        "required_inputs_complete": complete,
        "field_coverage": fields,
        "parsing_status": "parsed_required_inputs" if complete else "parsed_but_required_inputs_incomplete",
    }
    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

