import json

import framework_evidence

URL = "http://192.168.4.3:8080/output"
ARGV = ["curl", "-sS", "-i", "--max-time", "20", URL]

ALIASES = {
    "ciphertext": {"ciphertext", "cipher_text", "encrypted", "encrypted_data", "ct"},
    "encoding": {"encoding", "ciphertext_encoding", "data_encoding"},
    "iv_or_nonce": {"iv", "nonce", "initialization_vector", "initialisation_vector"},
    "cipher_details": {"cipher", "algorithm", "cipher_algorithm", "mode", "padding"},
    "related_parameters": {"key", "key_size", "salt", "tag", "aad", "parameters", "params"},
}


def find_stdout(value):
    if isinstance(value, dict):
        candidate = value.get("stdout")
        if isinstance(candidate, str):
            return candidate
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def classify(value, result):
    if isinstance(value, dict):
        for key, item in value.items():
            normalized = str(key).strip().lower().replace("-", "_").replace(" ", "_")
            for category, aliases in ALIASES.items():
                if normalized in aliases:
                    result.setdefault(category, []).append({"field": key, "value": item})
            classify(item, result)
    elif isinstance(value, list):
        for item in value:
            classify(item, result)


try:
    envelope = framework_evidence.run_tool(ARGV)
    output = {
        "provenance": {"url": URL, "method": "GET", "tool_argv": ARGV},
        "tool_observation": envelope,
    }
    raw_stdout = find_stdout(envelope)
    if raw_stdout is None:
        output["classification"] = {
            "status": "no_stdout_in_tool_envelope",
            "fields": {},
            "note": "The raw helper envelope is retained; response content could not be extracted for classification.",
        }
    else:
        body = raw_stdout
        separator = "\r\n\r\n"
        if separator in body:
            body = body.split(separator, 1)[1]
        else:
            separator = "\n\n"
            if separator in body:
                body = body.split(separator, 1)[1]
        parsed = None
        parse_error = None
        try:
            parsed = json.loads(body)
        except (json.JSONDecodeError, TypeError) as exc:
            parse_error = str(exc)
        fields = {}
        if parsed is not None:
            classify(parsed, fields)
        output["classification"] = {
            "status": "json_parsed" if parsed is not None else "body_not_json",
            "fields": fields,
            "body_parse_error": parse_error,
            "note": "An empty field list means no recognized field names were found in the parsed response; inspect the preserved raw tool observation for other formats or names.",
        }
    print(json.dumps(output, ensure_ascii=False))
except Exception as exc:
    print(json.dumps({
        "provenance": {"url": URL, "method": "GET", "tool_argv": ARGV},
        "status": "tool_invocation_error",
        "error_type": type(exc).__name__,
        "error": str(exc),
        "note": "No successful endpoint response is claimed.",
    }, ensure_ascii=False))

