import hashlib
import json
import re
import sys
import urllib.error
import urllib.request

BASE = "http://192.168.4.3:8080"


def fetch(path):
    req = urllib.request.Request(BASE + path, headers={"User-Agent": "crypto-challenge-decryption/1.0"})
    with urllib.request.urlopen(req, timeout=15) as response:
        body = response.read()
        return {
            "url": response.geturl(),
            "status": response.status,
            "headers": dict(response.headers.items()),
            "body": body,
            "sha256": hashlib.sha256(body).hexdigest(),
        }


def walk(obj):
    if isinstance(obj, dict):
        for key, value in obj.items():
            yield str(key), value
            yield from walk(value)
    elif isinstance(obj, list):
        for value in obj:
            yield "", value
            yield from walk(value)


def json_body(body):
    try:
        return json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None


def named_integer(data, names):
    wanted = {n.lower() for n in names}
    if data is not None:
        for key, value in walk(data):
            if key.lower() in wanted:
                if isinstance(value, int):
                    return value
                if isinstance(value, str):
                    text = value.strip()
                    try:
                        return int(text, 0) if text.lower().startswith("0x") else int(text, 10)
                    except ValueError:
                        pass
    return None


def ciphertext_from(data, raw_text):
    preferred = {"ciphertext", "encrypted", "encrypted_flag", "cipher", "output"}
    if data is not None:
        for key, value in walk(data):
            if key.lower() in preferred and isinstance(value, str):
                s = value.strip()
                if s.lower().startswith("0x"):
                    s = s[2:]
                s = re.sub(r"\s+", "", s)
                if s and re.fullmatch(r"[0-9a-fA-F]+", s) and len(s) % 32 == 0:
                    return bytes.fromhex(s), key
    patterns = [
        r"(?i)(?:ciphertext|encrypted(?:_flag)?|cipher|output)\s*[:=]\s*['\"](0x)?([0-9a-f]+)['\"]",
        r"(?i)(?:ciphertext|encrypted(?:_flag)?|cipher|output)[^\n]{0,80}?([0-9a-f]{32,})",
    ]
    for pattern in patterns:
        for match in re.finditer(pattern, raw_text):
            value = match.group(match.lastindex)
            if value and len(value) % 32 == 0:
                return bytes.fromhex(value), "text_match"
    if data is not None:
        candidates = []
        for key, value in walk(data):
            if isinstance(value, str):
                s = re.sub(r"\s+", "", value.strip())
                if s.lower().startswith("0x"):
                    s = s[2:]
                if len(s) >= 32 and len(s) % 32 == 0 and re.fullmatch(r"[0-9a-fA-F]+", s):
                    candidates.append((len(s), bytes.fromhex(s), key))
        if candidates:
            _, value, key = max(candidates, key=lambda item: item[0])
            return value, "hex_candidate:" + key
    raise ValueError("Could not identify a block-aligned ciphertext in the /output response")


# AES-128 primitives, implemented here to avoid non-standard-library dependencies.
def gf_mul(a, b):
    out = 0
    for _ in range(8):
        if b & 1:
            out ^= a
        a = ((a << 1) ^ (0x11B if a & 0x80 else 0)) & 0xFF
        b >>= 1
    return out


def gf_pow(a, n):
    out = 1
    while n:
        if n & 1:
            out = gf_mul(out, a)
        a = gf_mul(a, a)
        n >>= 1
    return out


def rot8(x, n):
    return ((x << n) | (x >> (8 - n))) & 0xFF


def make_sbox():
    box = []
    for x in range(256):
        inv = 0 if x == 0 else gf_pow(x, 254)
        box.append(inv ^ rot8(inv, 1) ^ rot8(inv, 2) ^ rot8(inv, 3) ^ rot8(inv, 4) ^ 0x63)
    inverse = [0] * 256
    for i, value in enumerate(box):
        inverse[value] = i
    return box, inverse


SBOX, INV_SBOX = make_sbox()


def expand_key(key):
    if len(key) != 16:
        raise ValueError("AES-128 requires a 16-byte key")
    words = [list(key[i:i + 4]) for i in range(0, 16, 4)]
    rcon = 1
    for i in range(4, 44):
        temp = words[i - 1][:]
        if i % 4 == 0:
            temp = temp[1:] + temp[:1]
            temp = [SBOX[x] for x in temp]
            temp[0] ^= rcon
            rcon = gf_mul(rcon, 2)
        words.append([words[i - 4][j] ^ temp[j] for j in range(4)])
    return [sum(words[4 * r:4 * r + 4], []) for r in range(11)]


def add_round_key(state, key):
    return [a ^ b for a, b in zip(state, key)]


def inv_shift_rows(state):
    out = state[:]
    for row in range(1, 4):
        for col in range(4):
            out[row + 4 * col] = state[row + 4 * ((col - row) % 4)]
    return out


def inv_mix_columns(state):
    out = state[:]
    for col in range(4):
        i = 4 * col
        a0, a1, a2, a3 = state[i:i + 4]
        out[i:i + 4] = [
            gf_mul(a0, 14) ^ gf_mul(a1, 11) ^ gf_mul(a2, 13) ^ gf_mul(a3, 9),
            gf_mul(a0, 9) ^ gf_mul(a1, 14) ^ gf_mul(a2, 11) ^ gf_mul(a3, 13),
            gf_mul(a0, 13) ^ gf_mul(a1, 9) ^ gf_mul(a2, 14) ^ gf_mul(a3, 11),
            gf_mul(a0, 11) ^ gf_mul(a1, 13) ^ gf_mul(a2, 9) ^ gf_mul(a3, 14),
        ]
    return out


def aes_decrypt_block(block, round_keys):
    state = add_round_key(list(block), round_keys[10])
    for rnd in range(9, 0, -1):
        state = inv_shift_rows(state)
        state = [INV_SBOX[x] for x in state]
        state = add_round_key(state, round_keys[rnd])
        state = inv_mix_columns(state)
    state = inv_shift_rows(state)
    state = [INV_SBOX[x] for x in state]
    state = add_round_key(state, round_keys[0])
    return bytes(state)


def decrypt_ecb(ciphertext, key):
    if not ciphertext or len(ciphertext) % 16:
        raise ValueError("Ciphertext must contain a non-empty whole number of AES blocks")
    keys = expand_key(key)
    plain = b"".join(aes_decrypt_block(ciphertext[i:i + 16], keys)
                    for i in range(0, len(ciphertext), 16))
    if not plain:
        raise ValueError("Decryption returned no bytes")
    pad = plain[-1]
    if 1 <= pad <= 16 and plain.endswith(bytes([pad]) * pad):
        plain = plain[:-pad]
    return plain


def main():
    result = {"purpose": "Decrypt service ciphertext using the observed exchange and service procedure."}
    try:
        source = fetch("/source")
        output = fetch("/output")
        source_text = source["body"].decode("utf-8", "replace")
        output_text = output["body"].decode("utf-8", "replace")
        out_data = json_body(output["body"])
        src_data = json_body(source["body"])
        result["responses"] = {
            "source": {k: v for k, v in source.items() if k != "body"},
            "output": {k: v for k, v in output.items() if k != "body"},
        }
        procedure_checks = {
            "aes_mentioned": "aes" in source_text.lower(),
            "ecb_mentioned": "ecb" in source_text.lower(),
            "sha256_mentioned": "sha256" in source_text.lower(),
            "long_to_bytes_mentioned": "long_to_bytes" in source_text.lower(),
        }
        result["procedure_checks"] = procedure_checks
        if not all(procedure_checks.values()):
            raise ValueError("Fetched /source did not visibly evidence all expected AES/ECB/SHA-256/long_to_bytes terms")

        p = named_integer(out_data, {"p"})
        g = named_integer(out_data, {"g"})
        pub_a = named_integer(out_data, {"pubA", "pub_a", "publica", "public_a"})
        pub_b = named_integer(out_data, {"pubB", "pub_b", "publicb", "public_b"})
        if None in (p, g, pub_a, pub_b):
            # Also accept Python-style text output with named integer assignments.
            for name, aliases in (("p", ["p"]), ("g", ["g"]),
                                  ("pub_a", ["pubA", "pub_a", "publicA"]),
                                  ("pub_b", ["pubB", "pub_b", "publicB"])):
                if locals().get(name) is not None:
                    continue
                for alias in aliases:
                    match = re.search(r"(?im)^\s*" + re.escape(alias) + r"\s*[:=]\s*['\"]?(\d+)", output_text)
                    if match:
                        if name == "p": p = int(match.group(1))
                        elif name == "g": g = int(match.group(1))
                        elif name == "pub_a": pub_a = int(match.group(1))
                        else: pub_b = int(match.group(1))
                        break
        if None in (p, g, pub_a, pub_b):
            raise ValueError("Could not extract p, g, pubA, and pubB from /output")
        if p <= 2 or g <= 0:
            raise ValueError("Invalid extracted Diffie-Hellman parameters")

        # The observed challenge evidence supports a private-exponent search through 1024.
        exp_a = next((x for x in range(1025) if pow(g, x, p) == pub_a), None)
        exp_b = next((x for x in range(1025) if pow(g, x, p) == pub_b), None)
        if exp_a is None or exp_b is None:
            raise ValueError("Could not reproduce both public values within the evidenced exponent range 0..1024")
        secret_a = pow(pub_b, exp_a, p)
        secret_b = pow(pub_a, exp_b, p)
        if secret_a != secret_b:
            raise ValueError("Independent shared-secret derivations do not agree")
        secret_bytes = (secret_a.to_bytes(max(1, (secret_a.bit_length() + 7) // 8), "big"))
        key = hashlib.sha256(secret_bytes).digest()
        ciphertext, ciphertext_source = ciphertext_from(out_data, output_text)
        plaintext = decrypt_ecb(ciphertext, key)
        result["exchange_checks"] = {
            "range_searched": [0, 1024],
            "private_exponent_a": exp_a,
            "private_exponent_b": exp_b,
            "public_a_reproduced": pow(g, exp_a, p) == pub_a,
            "public_b_reproduced": pow(g, exp_b, p) == pub_b,
            "shared_secret_derivations_agree": secret_a == secret_b,
            "shared_secret_decimal": str(secret_a),
            "key_derivation": "SHA-256 of minimal big-endian shared-secret bytes",
        }
        result["ciphertext"] = {"source_field": ciphertext_source, "bytes": len(ciphertext), "hex": ciphertext.hex()}
        result["decryption"] = {
            "algorithm": "AES-128-ECB",
            "plaintext_bytes": len(plaintext),
            "plaintext_hex": plaintext.hex(),
            "plaintext_utf8": plaintext.decode("utf-8", "replace"),
            "padding": "PKCS#7 removed when valid; otherwise raw decrypted bytes retained",
        }
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        result["error"] = {"type": type(exc).__name__, "message": str(exc)}
    except Exception as exc:
        result["error"] = {"type": type(exc).__name__, "message": str(exc)}
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

