import base64
import hashlib
import json
import re
import shutil
import subprocess
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://192.168.4.3:8080"
START_PATHS = ["/", "/output"]
MAX_BODY = 200000
TIMEOUT = 8


def request(url):
    req = urllib.request.Request(url, headers={"User-Agent": "evidence-check/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT) as response:
            body = response.read(MAX_BODY + 1)
            return {
                "url": url,
                "status": response.status,
                "headers": dict(response.headers.items()),
                "body": body[:MAX_BODY].decode("utf-8", "replace"),
                "truncated": len(body) > MAX_BODY,
                "error": None,
            }
    except Exception as exc:
        return {"url": url, "status": None, "headers": {}, "body": "", "truncated": False,
                "error": type(exc).__name__ + ": " + str(exc)}


def same_origin_links(page):
    links = []
    for href in re.findall(r'''(?:href|src)\s*=\s*["']([^"']+)["']''', page, re.I):
        absolute = urllib.parse.urljoin(BASE + "/", href)
        parsed = urllib.parse.urlparse(absolute)
        if parsed.scheme in ("http", "https") and parsed.netloc == urllib.parse.urlparse(BASE).netloc:
            path = parsed.path or "/"
            if parsed.query:
                path += "?" + parsed.query
            if path not in links and path not in START_PATHS:
                links.append(path)
    return links


def walk_strings(value, path="$", found=None):
    if found is None:
        found = []
    if isinstance(value, dict):
        for key, item in value.items():
            walk_strings(item, path + "." + str(key), found)
    elif isinstance(value, list):
        for index, item in enumerate(value):
            walk_strings(item, path + "[" + str(index) + "]", found)
    elif isinstance(value, str):
        found.append({"path": path, "value": value})
    return found


def decode_cipher(text):
    text = text.strip()
    if not text:
        return None
    compact = re.sub(r"\s+", "", text)
    try:
        if re.fullmatch(r"(?:[0-9a-fA-F]{2})+", compact):
            return bytes.fromhex(compact), "hex"
        return base64.b64decode(compact, validate=True), "base64"
    except Exception:
        return None


def main():
    observations = []
    seen = set()
    queue = list(START_PATHS)
    while queue and len(seen) < 16:
        path = queue.pop(0)
        if path in seen:
            continue
        seen.add(path)
        obs = request(urllib.parse.urljoin(BASE + "/", path.lstrip("/")))
        # urljoin with a leading slash is clearer and preserves query strings.
        obs = request(BASE.rstrip("/") + (path if path.startswith("/") else "/" + path))
        observations.append(obs)
        if obs["body"]:
            queue.extend(link for link in same_origin_links(obs["body"]) if link not in seen)

    report = {
        "purpose": "Compare observed service material with the prior AES key-length failure; source code is not executed.",
        "requests": observations,
        "crypto_relevant_source_lines": [],
        "structured_crypto_fields": [],
        "shared_secret_and_key": None,
        "decryption_attempt": {"status": "not_attempted", "reason": "Insufficient explicit service procedure or inputs."},
    }

    parsed_objects = []
    all_text = []
    for obs in observations:
        body = obs["body"]
        all_text.append(body)
        try:
            parsed = json.loads(body)
            parsed_objects.append((obs["url"], parsed))
            for item in walk_strings(parsed):
                if re.search(r"cipher|encrypt|decrypt|aes|sha|key|iv|source|code", item["path"], re.I):
                    report["structured_crypto_fields"].append({"url": obs["url"], **item})
        except Exception:
            pass
        for line_number, line in enumerate(body.splitlines(), 1):
            if re.search(r"AES|sha.?256|long_to_bytes|ciphertext|\.encrypt|\.decrypt|MODE_CBC|AES\.new|key\s*=|iv\s*=", line, re.I):
                report["crypto_relevant_source_lines"].append({"url": obs["url"], "line": line_number, "text": line[:1200]})

    params = {}
    ciphertext_value = None
    iv_value = None
    for _, obj in parsed_objects:
        if isinstance(obj, dict):
            for k, v in obj.items():
                lk = str(k).lower()
                if lk in ("p", "g", "puba", "pubb") and isinstance(v, (str, int)):
                    params[lk] = int(v)
                if isinstance(v, str):
                    if "cipher" in lk or lk in ("ct", "encrypted"):
                        ciphertext_value = v
                    if lk == "iv":
                        iv_value = v

    # The observed exchange verification identified exponents 210 and 416.
    if all(k in params for k in ("p", "g", "puba", "pubb")):
        p, g = params["p"], params["g"]
        checks = {"g_pow_210_matches_pubA": pow(g, 210, p) == params["puba"],
                  "g_pow_416_matches_pubB": pow(g, 416, p) == params["pubb"]}
        secret_a = pow(params["pubb"], 210, p)
        secret_b = pow(params["puba"], 416, p)
        if secret_a == secret_b and all(checks.values()):
            secret_bytes = secret_a.to_bytes(max(1, (secret_a.bit_length() + 7) // 8), "big")
            key = hashlib.sha256(secret_bytes).digest()
            report["shared_secret_and_key"] = {
                "verification": checks,
                "shared_secret_decimal": str(secret_a),
                "shared_secret_encoding": "minimal-width unsigned big-endian bytes",
                "shared_secret_bytes_hex": secret_bytes.hex(),
                "sha256_key_hex": key.hex(),
                "sha256_key_length_bytes": len(key),
            }
            source = "\n".join(all_text)
            # Decrypt only for explicit evidence of AES-CBC and how a 16-byte key is selected.
            cbc = bool(re.search(r"AES\.MODE_CBC|MODE_CBC|AES-?(?:128|256)-CBC|aes-(?:128|256)-cbc", source, re.I))
            trunc16 = bool(re.search(r"(?:key|sha256|digest)\s*\[\s*:?\s*16\s*\]", source, re.I))
            if ciphertext_value and iv_value and cbc and shutil.which("openssl"):
                cipher_data = decode_cipher(ciphertext_value)
                iv_data = decode_cipher(iv_value)
                if cipher_data and iv_data and len(iv_data[0]) == 16:
                    selected_key = key[:16] if trunc16 else key
                    if len(selected_key) in (16, 32) and len(cipher_data[0]) % 16 == 0:
                        aes_name = "aes-128-cbc" if len(selected_key) == 16 else "aes-256-cbc"
                        cmd = ["openssl", "enc", "-d", "-" + aes_name, "-K", selected_key.hex(), "-iv", iv_data[0].hex()]
                        try:
                            run = subprocess.run(cmd, input=cipher_data[0], stdout=subprocess.PIPE,
                                                 stderr=subprocess.PIPE, timeout=10, check=False)
                            report["decryption_attempt"] = {
                                "status": "completed" if run.returncode == 0 else "failed",
                                "procedure_basis": "Observed response explicitly indicates AES-CBC; key length follows the observed truncation expression when present, otherwise SHA-256 digest length.",
                                "command": cmd,
                                "exit_code": run.returncode,
                                "plaintext_bytes_utf8_replacement": run.stdout.decode("utf-8", "replace"),
                                "plaintext_hex": run.stdout.hex(),
                                "stderr": run.stderr.decode("utf-8", "replace"),
                            }
                        except Exception as exc:
                            report["decryption_attempt"] = {"status": "error", "error": type(exc).__name__ + ": " + str(exc)}
                    else:
                        report["decryption_attempt"]["reason"] = "Ciphertext or key length is inconsistent with AES-CBC block/key requirements."
                else:
                    report["decryption_attempt"]["reason"] = "Ciphertext or IV could not be decoded, or IV is not 16 bytes."
            elif not cbc:
                report["decryption_attempt"]["reason"] = "Retrieved responses do not explicitly establish AES-CBC; mode/padding procedure remains unknown."
            elif not ciphertext_value or not iv_value:
                report["decryption_attempt"]["reason"] = "A ciphertext and IV were not both present in retrieved structured service responses."
            else:
                report["decryption_attempt"]["reason"] = "OpenSSL executable was not available for the evidenced AES-CBC procedure."
        else:
            report["shared_secret_and_key"] = {"verification": checks, "status": "parameters did not validate against the observed exponents"}
    else:
        report["shared_secret_and_key"] = {"status": "service response did not expose all of p, g, pubA, pubB; no secret/key recomputed"}

    print(json.dumps(report, ensure_ascii=False))


if __name__ == "__main__":
    main()

