import hashlib
import html
import json
import re
import tempfile
import urllib.error
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.4.3:8080"
KNOWN_CIPHERTEXT = "15425e415d922ea063ac8c8e8228e8ed"


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, data):
        self.parts.append(data)


def fetch(path):
    req = urllib.request.Request(BASE + path, headers={"User-Agent": "crypto-procedure-verifier/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=15) as response:
            body = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
            return {"url": BASE + path, "status": response.status,
                    "headers": dict(response.headers.items()),
                    "body": body.decode(charset, errors="replace"), "error": None}
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        return {"url": BASE + path, "status": None, "headers": {},
                "body": None, "error": repr(exc)}


def visible_text(body):
    parser = TextExtractor()
    parser.feed(body or "")
    return html.unescape("\n".join(parser.parts))


def field_value(text, name):
    match = re.search(r"(?i)(?:^|[^A-Za-z0-9_])" + re.escape(name) +
                      r"\s*[:=]\s*['\"]?([0-9a-fA-F]+)", text)
    return match.group(1) if match else None


def number_value(text, name):
    match = re.search(r"(?i)(?:^|[^A-Za-z0-9_])" + re.escape(name) +
                      r"\s*[:=]\s*['\"]?([0-9]+)", text)
    return int(match.group(1)) if match else None


def collect_stdout(value):
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        runs = value.get("tool_runs")
        if isinstance(runs, list) and runs:
            for run in runs:
                found = collect_stdout(run)
                if found is not None:
                    return found
    return None


def main():
    source_resp = fetch("/source")
    output_resp = fetch("/output")
    source_text = visible_text(source_resp["body"])
    output_text = visible_text(output_resp["body"])

    # Search both rendered text and response markup; retain the original responses below.
    combined_output = output_text + "\n" + (output_resp["body"] or "")
    p = number_value(combined_output, "p")
    g = number_value(combined_output, "g")
    pub_a = number_value(combined_output, "pubA")
    pub_b = number_value(combined_output, "pubB")
    ciphertext = field_value(combined_output, "ciphertext")
    if not ciphertext:
        ciphertext_match = re.search(r"(?i)\bciphertext\b[^0-9a-fA-F]{0,40}([0-9a-fA-F]{16,})", combined_output)
        if ciphertext_match:
            ciphertext = ciphertext_match.group(1)
    if not ciphertext and output_resp.get("status") == 200:
        # This value was directly observed in the earlier HTTP 200 response.
        ciphertext = KNOWN_CIPHERTEXT

    result = {
        "purpose": "Compare live service source and inputs with the AES key-length failure, then attempt only a source-indicated decryption.",
        "source_response": source_resp,
        "output_response": output_resp,
        "source_visible_text": source_text,
        "extracted_inputs": {"p": p, "g": g, "pubA": pub_a, "pubB": pub_b,
                             "ciphertext_hex": ciphertext,
                             "ciphertext_fallback": bool(ciphertext == KNOWN_CIPHERTEXT and not field_value(combined_output, "ciphertext"))},
        "prior_error_context": "The prior attempt reported ValueError: AES-128 requires a 16-byte key; the reported service derivation was SHA-256(long_to_bytes(shared_secret)), whose digest is 32 bytes. This script independently checks the live procedure and inputs.",
        "shared_secret_check": None,
        "key_derivation": None,
        "decryption": {"status": "not_attempted", "reason": None}
    }

    src = source_text or ""
    mode_match = re.search(r"(?i)MODE_(ECB|CBC|CTR|OFB|CFB|GCM)\b", src)
    mode = mode_match.group(1).upper() if mode_match else None
    sha256_mentioned = bool(re.search(r"(?i)sha\s*[-_]?(?:256|2\s*\(\s*256\s*\))", src) or "sha256" in src.lower())
    long_to_bytes_mentioned = "long_to_bytes" in src
    key_procedure = {"sha256_indicated": sha256_mentioned,
                     "long_to_bytes_indicated": long_to_bytes_mentioned,
                     "aes_mode_indicated": mode,
                     "source_mentions_unpadding": bool(re.search(r"(?i)unpad|pkcs\s*#?7", src)),
                     "source_mentions_padding": bool(re.search(r"(?i)pad\s*\(", src))}
    result["source_procedure_checks"] = key_procedure

    missing = [name for name, value in (("p", p), ("g", g), ("pubA", pub_a), ("pubB", pub_b)) if value is None]
    secret = None
    exponent_pair = None
    if not missing and p > 1 and g > 0:
        a = next((x for x in range(1025) if pow(g, x, p) == pub_a), None)
        b = next((x for x in range(1025) if pow(g, x, p) == pub_b), None)
        if a is not None and b is not None:
            secret_a = pow(pub_b, a, p)
            secret_b = pow(pub_a, b, p)
            result["shared_secret_check"] = {
                "search_range": "0..1024 inclusive for each public value",
                "exponent_for_pubA": a, "exponent_for_pubB": b,
                "pubA_match": pow(g, a, p) == pub_a,
                "pubB_match": pow(g, b, p) == pub_b,
                "two_peer_derivations_agree": secret_a == secret_b
            }
            if secret_a == secret_b:
                secret = secret_a
                exponent_pair = (a, b)
        else:
            result["shared_secret_check"] = {"search_range": "0..1024 inclusive", "exponent_for_pubA": a,
                                              "exponent_for_pubB": b, "verified": False}
    else:
        result["shared_secret_check"] = {"verified": False, "missing_fields": missing,
                                          "reason": "Required live service parameters were not all parsed."}

    if secret is not None:
        secret_bytes = secret.to_bytes(max(1, (secret.bit_length() + 7) // 8), "big")
        key = hashlib.sha256(secret_bytes).digest()
        result["key_derivation"] = {
            "shared_secret_decimal": str(secret),
            "shared_secret_minimal_big_endian_hex": secret_bytes.hex(),
            "sha256_key_hex": key.hex(), "key_bytes": len(key),
            "comparison": "SHA-256 of minimal unsigned big-endian shared-secret bytes; 32 bytes, not an AES-128 key."
        }

    if not source_resp.get("body") or source_resp.get("status") != 200:
        result["decryption"] = {"status": "not_attempted", "reason": "Could not retrieve HTTP 200 source; procedure is not evidenced."}
    elif not output_resp.get("body") or output_resp.get("status") != 200:
        result["decryption"] = {"status": "not_attempted", "reason": "Could not retrieve HTTP 200 service inputs."}
    elif secret is None:
        result["decryption"] = {"status": "not_attempted", "reason": "Shared secret was not independently recomputed from complete live parameters."}
    elif not sha256_mentioned or not long_to_bytes_mentioned:
        result["decryption"] = {"status": "not_attempted", "reason": "The exact source did not explicitly evidence both SHA-256 and long_to_bytes key derivation."}
    elif mode not in ("ECB", "CBC", "CTR", "OFB", "CFB"):
        result["decryption"] = {"status": "not_attempted", "reason": "Source does not identify a supported AES mode unambiguously."}
    elif not ciphertext or len(ciphertext) % 2:
        result["decryption"] = {"status": "not_attempted", "reason": "Ciphertext was absent or not valid even-length hexadecimal."}
    else:
        iv = None
        # Accept only an explicit hexadecimal IV literal in the source.
        iv_match = re.search(r"(?i)(?:iv\s*=\s*)?(?:bytes\.fromhex\s*\(\s*|b['\"])([0-9a-f]{32})(?:['\"]\s*\))?", src)
        if iv_match:
            iv = iv_match.group(1).lower()
        if mode in ("CBC", "CTR", "OFB", "CFB") and iv is None:
            result["decryption"] = {"status": "not_attempted", "reason": "The source indicates an IV-based AES mode but no unambiguous 16-byte hexadecimal IV literal was extracted."}
        else:
            try:
                ciphertext_bytes = bytes.fromhex(ciphertext)
                if mode in ("ECB", "CBC") and len(ciphertext_bytes) % 16:
                    raise ValueError("block-mode ciphertext length is not a multiple of 16 bytes")
                import framework_evidence
                cipher_file = tempfile.NamedTemporaryFile(prefix="crypto-evidence-", delete=True)
                cipher_file.write(ciphertext_bytes)
                cipher_file.flush()
                cipher_name = cipher_file.name
                algorithm = "aes-256-" + mode.lower()
                argv = ["openssl", "enc", "-d", "-" + algorithm, "-nopad", "-K", key.hex(), "-in", cipher_name]
                if mode in ("CBC", "CTR", "OFB", "CFB"):
                    argv.extend(["-iv", iv])
                envelope = framework_evidence.run_tool(argv)
                cipher_file.close()
                stdout = collect_stdout(envelope)
                raw_hex = None
                plaintext_text = None
                if stdout is not None:
                    # Tool wrappers generally expose binary stdout using a text encoding. For
                    # successful block decryptions OpenSSL output may contain non-UTF8 bytes;
                    # base64/hex are retained when the wrapper provides them as structured data.
                    raw_hex = envelope.get("stdout_hex") if isinstance(envelope, dict) else None
                    if not raw_hex:
                        try:
                            raw_hex = stdout.encode("latin-1").hex()
                        except UnicodeEncodeError:
                            raw_hex = None
                    try:
                        plaintext_text = stdout
                    except Exception:
                        pass
                result["decryption"] = {
                    "status": "tool_attempt_completed" if stdout is not None else "tool_attempted_output_unavailable",
                    "source_mode": mode, "openssl_algorithm": algorithm,
                    "key_hex": key.hex(), "iv_hex": iv,
                    "ciphertext_hex": ciphertext_bytes.hex(),
                    "openssl_argv": argv, "tool_envelope": envelope,
                    "plaintext_raw_hex_if_recoverable": raw_hex,
                    "plaintext_text_if_recoverable": plaintext_text,
                    "interpretation": "Raw decryption output is not independently validated as a flag. OpenSSL was invoked with -nopad; any source-indicated unpadding must be assessed from the retained raw bytes."
                }
            except Exception as exc:
                result["decryption"] = {"status": "attempt_failed", "reason": repr(exc),
                                        "note": "No plaintext is claimed; source and input evidence remain in this record."}

    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()
